import React from "react";
import { Line } from "react-chartjs-2";
import { Card } from "react-bootstrap";

const ComparisonCharts = ({ results }) => {

  if (!results || !results.rewards) {
    return <p>Run simulation to see results.</p>;
  }

  const chartData = {
    labels: results.rewards.map((_, i) => i + 1),
    datasets: [
      {
        label: "Reward per Episode",
        data: results.rewards,
        borderColor: "rgba(75,192,192,1)",
        backgroundColor: "rgba(75,192,192,0.2)",
        fill: true
      }
    ]
  };

  const options = {
    responsive: true,
    plugins: {
      title: {
        display: true,
        text: 'Reward per Episode'
      }
    },
    scales: {
      x: {
        title: {
          display: true,
          text: 'Episode'
        }
      },
      y: {
        title: {
          display: true,
          text: 'Reward'
        },
        beginAtZero: false
      }
    }
  };

  return (
    <Card className="mb-4">
      <Card.Body>
        <Card.Title>Reward per Episode</Card.Title>
        <Line redraw data={chartData} options={options} />
      </Card.Body>
    </Card>
  );
};

export default ComparisonCharts;
